import Header from '../components/Header';
import Footer from '../components/Footer';
import { useState, useContext } from 'react';
import { PreferencesContext } from '../context/indexContext';
import '../styles/Preferences.css';

function Preferences() {
    const { mode, setMode } = useContext(PreferencesContext);

    function CheckboxChange(e) {
        setMode(e.target.checked);
    }

    return (
        <div className={`preferences-page ${mode}-mode`}>
            <Header />

            <h1>Préférences</h1>

            <label>
                <input
                    type="radio"
                    name="theme"
                    checked={mode === "default"}
                    onChange={() => setMode("default")}
                />
                Mode Zikéolarge #SouslOcean
            </label>

            <label>
                <input
                    type="radio"
                    name="theme"
                    checked={mode === "maya"}
                    onChange={() => setMode("maya")}
                />
                Mode zzzzzzzzzzzzzzzzzzzzzzzzikeo #MayalAbeille
            </label>

            <label>
                <input
                    type="radio"
                    name="theme"
                    checked={mode === "ocean"}
                    onChange={() => setMode("ocean")}
                />
                Mode Zikéolienne #EnRotationDansLeVent
            </label>

            <label>
                <input
                    type="radio"
                    name="theme"
                    checked={mode === "dark"}
                    onChange={() => setMode("dark")}
                />
                Mode Zikéolit #
            </label>

            <label>
                <input
                    type="radio"
                    name="theme"
                    checked={mode === "retro"}
                    onChange={() => setMode("retro")}
                />
                Mode Retro
            </label>

            <Footer />

        </div>
    )
}

export default Preferences;
